// Generates index.html for every page in site/catalog.mjs, plus public/sitemap.xml.
// The generated files are committed so `vite` can serve them directly; this
// script runs before dev and build, and `--check` fails if they are stale.
import { mkdir, readFile, writeFile } from "node:fs/promises";
import { dirname, resolve } from "node:path";
import {
  CONTACT_EMAIL,
  PRIVACY_NOTE,
  PRIVACY_PAGE,
  SITE,
  TOOLS,
  toolUrl,
} from "../site/catalog.mjs";

const root = resolve(import.meta.dirname, "..");
const check = process.argv.includes("--check");

const escapeHtml = (value) =>
  String(value)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;");

const jsonLd = (value) => JSON.stringify(value, null, 2).replaceAll("<", "\\u003c");

const LOCK = `<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect width="18" height="11" x="3" y="11" rx="2"/><path d="M7 11V7a5 5 0 0 1 10 0v4"/><circle cx="12" cy="16" r="1"/></svg>`;
const MARK = `<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M15 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V7Z"/><path d="M14 2v4a2 2 0 0 0 2 2h4"/><path d="M10 9H8"/><path d="M16 13H8"/><path d="M16 17H8"/></svg>`;

function relative(from, to) {
  const up = from.slug ? "../" : "./";
  return to.slug ? `${up}${to.slug}/` : up;
}

function siteBar(current) {
  const links = TOOLS.map(
    (tool) =>
      `          <li><a href="${relative(current, tool)}"${tool.id === current.id ? ' aria-current="page"' : ""}>${escapeHtml(tool.nav)}</a></li>`,
  ).join("\n");
  return `    <header class="site-bar">
      <a class="wordmark" href="${relative(current, TOOLS[0])}" aria-label="PDF Editor home">
        <span class="wordmark-icon">${MARK}</span>
        <span>PDF<span class="wordmark-light">Editor</span></span>
      </a>
      <nav class="site-nav" aria-label="PDF tools">
        <ul>
${links}
        </ul>
      </nav>
      <span class="site-privacy">${LOCK}Files never leave this device</span>
    </header>`;
}

function structuredData(tool) {
  const url = toolUrl(tool);
  const graph = [
    {
      "@type": "WebApplication",
      "@id": `${url}#app`,
      name: tool.id === "edit" ? SITE.name : tool.name,
      url,
      description: tool.description,
      applicationCategory: "BusinessApplication",
      operatingSystem: "Any (modern web browser)",
      browserRequirements:
        "Requires JavaScript and a modern browser such as Chrome, Edge, Firefox or Safari.",
      isAccessibleForFree: true,
      offers: { "@type": "Offer", price: "0", priceCurrency: "USD" },
      featureList: tool.featureList,
      screenshot: `${SITE.origin}${SITE.base}og-image.png`,
    },
    {
      "@type": "FAQPage",
      mainEntity: tool.faq.map(({ q, a }) => ({
        "@type": "Question",
        name: q,
        acceptedAnswer: { "@type": "Answer", text: a },
      })),
    },
  ];
  if (tool.slug) {
    graph.push({
      "@type": "BreadcrumbList",
      itemListElement: [
        { "@type": "ListItem", position: 1, name: SITE.name, item: toolUrl(TOOLS[0]) },
        { "@type": "ListItem", position: 2, name: tool.name, item: url },
      ],
    });
  }
  return jsonLd({ "@context": "https://schema.org", "@graph": graph });
}

function guide(tool) {
  if (tool.features) {
    return `          <section aria-labelledby="features-title">
            <h2 id="features-title">What you can do</h2>
            <ul>
${tool.features.map(([title, text]) => `              <li><strong>${escapeHtml(title)}</strong> ${escapeHtml(text)}</li>`).join("\n")}
            </ul>
          </section>`;
  }
  return `          <section aria-labelledby="steps-title">
            <h2 id="steps-title">${escapeHtml(tool.howTo)}</h2>
            <ol>
${tool.steps.map((step) => `              <li>${escapeHtml(step)}</li>`).join("\n")}
            </ol>
          </section>`;
}

function headTags(tool) {
  const url = toolUrl(tool);
  return `    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <!-- Generated by scripts/build-pages.mjs from site/catalog.mjs. Edit those, not this file. -->
    <title>${escapeHtml(tool.title)}</title>
    <meta name="description" content="${escapeHtml(tool.description)}" />
    <link rel="canonical" href="${url}" />
    <meta name="robots" content="index, follow, max-image-preview:large" />
    <meta name="theme-color" content="#1d2536" />
    <link rel="icon" type="image/svg+xml" href="/favicon.svg" />
    <link rel="apple-touch-icon" href="/apple-touch-icon.png" />

    <meta property="og:type" content="website" />
    <meta property="og:site_name" content="${SITE.name}" />
    <meta property="og:title" content="${escapeHtml(tool.title)}" />
    <meta property="og:description" content="${escapeHtml(tool.description)}" />
    <meta property="og:url" content="${url}" />
    <meta property="og:image" content="${SITE.origin}${SITE.base}og-image.png" />
    <meta property="og:image:width" content="1200" />
    <meta property="og:image:height" content="630" />
    <meta property="og:image:alt" content="PDF Editor with a two-page agreement open, page thumbnails on the left and editing tools above." />
    <meta property="og:locale" content="en_US" />
    <meta name="twitter:card" content="summary_large_image" />
    <meta name="twitter:title" content="${escapeHtml(tool.title)}" />
    <meta name="twitter:description" content="${escapeHtml(tool.description)}" />
    <meta name="twitter:image" content="${SITE.origin}${SITE.base}og-image.png" />`;
}

function siteFooter(current) {
  return `        <footer class="site-footer">
          <p>
            Open source on <a href="${SITE.repo}">GitHub</a>. This site uses Google Analytics to
            count visits and which tools are used. File names and document contents are never sent.
          </p>
          <p>
            <a href="${relative(current, PRIVACY_PAGE)}">Privacy policy</a> · Contact:
            <a href="mailto:${CONTACT_EMAIL}">${CONTACT_EMAIL}</a>
          </p>
        </footer>`;
}

function page(tool) {
  const others = TOOLS.filter((other) => other.id !== tool.id);
  return `<!doctype html>
<html lang="en">
  <head>
${headTags(tool)}

    <script type="application/ld+json">
${structuredData(tool)}
    </script>
  </head>
  <body data-tool="${tool.id}">
    <a class="skip-link" href="#root">Skip to ${escapeHtml(tool.name.toLowerCase())}</a>
${siteBar(tool)}
    <div id="root"></div>
    <noscript>
      <p class="noscript-note">${escapeHtml(tool.name)} needs JavaScript to work with files in your browser. Enable JavaScript and reload the page.</p>
    </noscript>

    <section class="about" aria-labelledby="about-title">
      <div class="about-inner">
        <h1 id="about-title">${escapeHtml(tool.h1)}</h1>
        <p class="about-lead">${escapeHtml(tool.lead)}</p>

        <div class="about-grid">
${guide(tool)}

          <section aria-labelledby="privacy-title">
            <h2 id="privacy-title">How your files are handled</h2>
            <p>${escapeHtml(tool.privacy ?? PRIVACY_NOTE)}</p>
          </section>
        </div>

        <section class="faq" aria-labelledby="faq-title">
          <h2 id="faq-title">Questions</h2>
          <dl>
${tool.faq.map(({ q, a }) => `            <dt>${escapeHtml(q)}</dt>\n            <dd>${escapeHtml(a)}</dd>`).join("\n")}
          </dl>
        </section>

        <nav class="more-tools" aria-labelledby="more-title">
          <h2 id="more-title">More PDF tools</h2>
          <ul>
${others.map((other) => `            <li><a href="${relative(tool, other)}">${escapeHtml(other.name)}</a></li>`).join("\n")}
          </ul>
        </nav>

${siteFooter(tool)}
      </div>
    </section>
    <script type="module" src="${tool.entry}"></script>
  </body>
</html>
`;
}

function privacyPage() {
  const item = PRIVACY_PAGE;
  const data = jsonLd({
    "@context": "https://schema.org",
    "@type": "WebPage",
    name: item.title,
    url: toolUrl(item),
    description: item.description,
  });
  const sections = item.sections
    .map(
      ({ heading, body }) => `          <section>
            <h2>${escapeHtml(heading)}</h2>
            ${body.join("\n            ")}
          </section>`,
    )
    .join("\n");
  return `<!doctype html>
<html lang="en">
  <head>
${headTags(item)}

    <script type="application/ld+json">
${data}
    </script>
  </head>
  <body data-tool="${item.id}">
    <a class="skip-link" href="#policy">Skip to the privacy policy</a>
${siteBar(item)}
    <main class="about" id="policy">
      <div class="about-inner">
        <h1>${escapeHtml(item.h1)}</h1>
        <p class="about-lead">${escapeHtml(item.lead)}</p>
        <p class="policy-updated">Last updated ${escapeHtml(item.updated)}</p>

        <div class="policy">
${sections}
        </div>

${siteFooter(item)}
      </div>
    </main>
    <script type="module" src="${item.entry}"></script>
  </body>
</html>
`;
}

function sitemap() {
  const priority = (item) => (item === PRIVACY_PAGE ? "0.3" : item.slug ? "0.8" : "1.0");
  const urls = [...TOOLS, PRIVACY_PAGE]
    .map(
      (item) =>
        `  <url>\n    <loc>${toolUrl(item)}</loc>\n    <changefreq>monthly</changefreq>\n    <priority>${priority(item)}</priority>\n  </url>`,
    )
    .join("\n");
  return `<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n${urls}\n</urlset>\n`;
}

const outputs = [
  ...TOOLS.map((tool) => [resolve(root, tool.slug, "index.html"), page(tool)]),
  [resolve(root, PRIVACY_PAGE.slug, "index.html"), privacyPage()],
  [resolve(root, "public/sitemap.xml"), sitemap()],
];

let stale = 0;
for (const [path, content] of outputs) {
  const current = await readFile(path, "utf8").catch(() => "");
  if (current === content) continue;
  if (check) {
    console.error(`Out of date: ${path}. Run npm run pages.`);
    stale += 1;
    continue;
  }
  await mkdir(dirname(path), { recursive: true });
  await writeFile(path, content);
}
if (stale) process.exit(1);

export const htmlInputs = [...TOOLS, PRIVACY_PAGE].map((item) =>
  resolve(root, item.slug, "index.html"),
);
